from dataclasses import asdict, dataclass, fields



@dataclass
class ToolResult:
    """Represents the result of a tool execution."""

    output: str | None = None
    error: str | None = None

    def __bool__(self):
        return any(getattr(self, field.name) for field in fields(self))

    def to_dict(self, extra_field: dict | None = None) -> dict:
        result = asdict(self)

        # Add extra fields if provided
        if extra_field:
            result.update(extra_field)
        return result


@dataclass
class CLIResult(ToolResult):
    """A ToolResult that can be rendered as a CLI output."""

    # Optional fields for file editing commands
    path: str | None = None
    prev_exist: bool = True
    old_content: str | None = None
    new_content: str | None = None


def maybe_truncate(
    content: str,
    truncate_after: int | None = MAX_RESPONSE_LEN_CHAR,
    truncate_notice: str = CONTENT_TRUNCATED_NOTICE,
) -> str:
    """
    Truncate content and append a notice if content exceeds the specified length.
    """
    return (
        content
        if not truncate_after or len(content) <= truncate_after
        else content[:truncate_after] + truncate_notice
    )

# ---- openhands_aci/utils/shell.py ----
import os
import subprocess
import time



def run_shell_cmd(
    cmd: str,
    timeout: float | None = 120.0,  # seconds
    truncate_after: int | None = MAX_RESPONSE_LEN_CHAR,
    truncate_notice: str = CONTENT_TRUNCATED_NOTICE,
) -> tuple[int, str, str]:
    """Run a shell command synchronously with a timeout.

    Args:
        cmd: The shell command to run.
        timeout: The maximum time to wait for the command to complete.
        truncate_after: The maximum number of characters to return for stdout and stderr.

    Returns:
        A tuple containing the return code, stdout, and stderr.
    """

    start_time = time.time()

    try:
        process = subprocess.Popen(
            cmd, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True
        )

        stdout, stderr = process.communicate(timeout=timeout)

        return (
            process.returncode or 0,
            maybe_truncate(
                stdout, truncate_after=truncate_after, truncate_notice=truncate_notice
            ),
            maybe_truncate(
                stderr,
                truncate_after=truncate_after,
                truncate_notice=CONTENT_TRUNCATED_NOTICE,
            ),  # Use generic notice for stderr
        )
    except subprocess.TimeoutExpired:
        process.kill()
        elapsed_time = time.time() - start_time
        raise TimeoutError(
            f"Command '{cmd}' timed out after {elapsed_time:.2f} seconds"
        )


def check_tool_installed(tool_name: str) -> bool:
    """Check if a tool is installed."""
    try:
        subprocess.run(
            [tool_name, '--version'],
            check=True,
            cwd=os.getcwd(),
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
        )
        return True
    except (subprocess.CalledProcessError, FileNotFoundError):
        return False

# ---- stdlib shims for openhands-aci's third-party dependencies ----
import collections as _collections
import types as _types


def is_binary(path):
    """binaryornot.check.is_binary replacement: NUL byte or undecodable, mostly non-text prefix."""
    with open(path, 'rb') as f:
        chunk = f.read(1024)
    if not chunk:
        return False
    if b'\x00' in chunk:
        return True
    try:
        chunk.decode('utf-8')
        return False
    except UnicodeDecodeError:
        text = bytes(range(32, 127)) + b'\n\r\t\f\b'
        return sum(b not in text for b in chunk) / len(chunk) > 0.30


def _detect(raw_data):
    try:
        raw_data.decode('utf-8')
        return {'encoding': 'utf-8', 'confidence': 1.0}
    except UnicodeDecodeError:
        return {'encoding': 'latin-1', 'confidence': 0.5}


charset_normalizer = _types.SimpleNamespace(detect=_detect)


class LRUCache(_collections.OrderedDict):
    """cachetools.LRUCache replacement (maxsize-bounded, least recently used evicted)."""

    def __init__(self, maxsize=128, **kwargs):
        super().__init__()
        self.maxsize = maxsize

    def __getitem__(self, key):
        value = super().__getitem__(key)
        self.move_to_end(key)
        return value

    def __setitem__(self, key, value):
        super().__setitem__(key, value)
        self.move_to_end(key)
        while len(self) > self.maxsize:
            self.popitem(last=False)


class DefaultLinter:
    def lint_file_diff(self, *args, **kwargs):
        return []


class MarkdownConverter:
    def convert(self, path):
        raise RuntimeError('converting office/audio files to Markdown is not supported in this environment')

